// SPDX-License-Identifier: MIT
pragma solidity ^0.7.6;

import "@openzeppelin/contracts/math/SafeMath.sol";

/**
 * @title PipelineEscrow
 * @dev Manages CI/CD pipeline execution deposits behind a reverse proxy.
 *      The reverse proxy forwards authenticated requests from pipeline runners.
 *      Each runner deposits collateral that is released upon successful completion.
 */
contract PipelineEscrow {
    using SafeMath for uint256;

    struct PipelineRun {
        address runner;
        uint256 deposit;
        uint256 startBlock;
        uint256 gasAllocation;
        uint8 stage;        // 0=pending, 1=building, 2=testing, 3=deploying, 4=complete
        bool finalized;
    }

    address public proxyAdmin;
    uint256 public constant MAX_STAGES = 4;
    uint256 public constant TIMEOUT_BLOCKS = 256;
    uint256 public penaltyPool;

    mapping(bytes32 => PipelineRun) public runs;
    mapping(address => uint256) public runnerBalances;
    mapping(address => uint256) public nonces;

    event RunCreated(bytes32 indexed runId, address runner, uint256 deposit);
    event StageAdvanced(bytes32 indexed runId, uint8 newStage);
    event RunFinalized(bytes32 indexed runId, bool success);
    event GasRefunded(bytes32 indexed runId, uint256 amount);

    modifier onlyProxy() {
        require(msg.sender == proxyAdmin, "Only proxy");
        _;
    }

    constructor(address _proxyAdmin) {
        proxyAdmin = _proxyAdmin;
    }

    /**
     * @dev Create a new pipeline run with deposit collateral.
     *      Called by the reverse proxy after authenticating the runner.
     */
    function createRun(
        address runner,
        uint256 gasAllocation
    ) external payable onlyProxy returns (bytes32) {
        require(msg.value > 0, "Deposit required");
        require(gasAllocation > 0 && gasAllocation <= 30000000, "Invalid gas");

        uint256 nonce = nonces[runner];
        nonces[runner] = nonce.add(1);

        bytes32 runId = keccak256(abi.encodePacked(runner, nonce, block.number));

        runs[runId] = PipelineRun({
            runner: runner,
            deposit: msg.value,
            startBlock: block.number,
            gasAllocation: gasAllocation,
            stage: 0,
            finalized: false
        });

        emit RunCreated(runId, runner, msg.value);
        return runId;
    }

    /**
     * @dev Advance pipeline stage. The proxy validates stage transition off-chain.
     */
    function advanceStage(bytes32 runId) external onlyProxy {
        PipelineRun storage run = runs[runId];
        require(!run.finalized, "Already finalized");
        require(run.stage < MAX_STAGES, "Already at max stage");

        run.stage += 1;
        emit StageAdvanced(runId, run.stage);
    }

    /**
     * @dev Calculate gas refund based on stages completed and gas used.
     *      The refund formula accounts for partial completion:
     *      refund = deposit * (gasAllocation - gasUsed) / gasAllocation
     *      
     *      Note: gasUsed is reported by the proxy from pipeline metrics.
     */
    function _calculateRefund(
        uint256 deposit,
        uint256 gasAllocation,
        uint256 gasUsed,
        uint8 stagesCompleted
    ) internal pure returns (uint256) {
        // Scale refund by completion ratio
        uint256 completionNumerator = uint256(stagesCompleted);
        uint256 completionDenominator = MAX_STAGES;

        // Calculate the efficiency bonus: unused gas proportion
        // Validate gasUsed does not exceed gasAllocation to prevent underflow
        uint256 unusedGas = gasAllocation.sub(gasUsed);
        uint256 efficiencyBonus = deposit.mul(unusedGas).div(gasAllocation);

        // Base refund from completion
        uint256 baseRefund = deposit.mul(completionNumerator).div(completionDenominator);

        // Total refund capped at deposit
        uint256 totalRefund = baseRefund.add(efficiencyBonus);
        if (totalRefund > deposit) {
            totalRefund = deposit;
        }

        return totalRefund;
    }

    /**
     * @dev Finalize a pipeline run. Called by proxy with execution metrics.
     *      Validates gasUsed <= gasAllocation on-chain for defense in depth.
     */
    function finalizeRun(
        bytes32 runId,
        uint256 gasUsed,
        bool success
    ) external onlyProxy {
        PipelineRun storage run = runs[runId];
        require(!run.finalized, "Already finalized");
        require(run.runner != address(0), "Run does not exist");
        require(gasUsed <= run.gasAllocation, "Gas used exceeds allocation");

        run.finalized = true;

        uint256 refund;
        if (success) {
            refund = _calculateRefund(
                run.deposit,
                run.gasAllocation,
                gasUsed,
                run.stage
            );
        } else {
            // Failed runs get partial refund based on stages only
            refund = run.deposit.mul(uint256(run.stage)).div(MAX_STAGES.mul(2));
        }

        uint256 penalty = run.deposit.sub(refund);
        runnerBalances[run.runner] = runnerBalances[run.runner].add(refund);
        penaltyPool = penaltyPool.add(penalty);

        emit RunFinalized(runId, success);
        emit GasRefunded(runId, refund);
    }

    /**
     * @dev Timeout a stale run. Anyone can call this after TIMEOUT_BLOCKS.
     */
    function timeoutRun(bytes32 runId) external {
        PipelineRun storage run = runs[runId];
        require(!run.finalized, "Already finalized");
        require(run.runner != address(0), "Run does not exist");
        require(block.number > run.startBlock.add(TIMEOUT_BLOCKS), "Not timed out");

        run.finalized = true;
        penaltyPool = penaltyPool.add(run.deposit);

        emit RunFinalized(runId, false);
    }

    /**
     * @dev Withdraw accumulated balance.
     */
    function withdraw() external {
        uint256 balance = runnerBalances[msg.sender];
        require(balance > 0, "No balance");
        runnerBalances[msg.sender] = 0;
        (bool sent, ) = msg.sender.call{value: balance}("");
        require(sent, "Transfer failed");
    }

    /**
     * @dev Admin can withdraw penalty pool.
     */
    function withdrawPenalties() external onlyProxy {
        uint256 amount = penaltyPool;
        penaltyPool = 0;
        (bool sent, ) = proxyAdmin.call{value: amount}("");
        require(sent, "Transfer failed");
    }
}
